
import React, { useState } from "react";

import "./dashboard.css"
import { CloseModal } from "../../../components/DialogHRM";
import { SelectDropAccount_Cmpt } from "../../ComprobanteParametrizados";
import { getStore, gen16CodeId } from "../../../stores/Utils";


const DropInput = SelectDropAccount_Cmpt();


const LinkAccountPick = ({data, confirm, item}) => {
	const [obs, set_obs] = useState(0);
	const [acc, setAcc] = useState({});
	const [edit, setEdit] = useState(false);
	let account = acc?.account || item?.account; 
	let sub_account = acc?.subAccount || item?.subAccount; 

	let accountD = getStore("account_ids")?.[account];
	let subaccountD = getStore("sub_account_ids")?.[sub_account];


	const addExtraAccount2List = () => {
		confirm && confirm(acc);
		CloseModal({id:data.modalID})
	}

	const handlePick = (acc,subacc) => {
		let nn= {
			"account":acc,
			"subAccount":subacc
		}
		setAcc(nn);
		setEdit(false);
		set_obs(gen16CodeId())
	}


	
	
	const clear = () => {
		setEdit(true);
		set_obs(gen16CodeId())
	};

	return (
		<div style={{
			maxHeight: "80vh",
			minHeight: "60vh",
			width: "560px",
			overflow: "auto",
			background: "#fff",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					Associar Cuenta
				</p>
				<div className="flexSpace"/>
				
			</div>
		{!edit ? 
			<div className="_dsplFlx " style={{margin: "38px 0"}}>
				<div className=" acc_dtls">
					<div className="_dsplFlx"   onClick={clear}>
						<div className="code" style={{color: "#646cff"}}>
							{accountD?.code?accountD?.code:"Selecionar cuentas"} 
						</div>
						<div className="name">
							{accountD?.name}
						</div>
					</div>
					{subaccountD ?
						<div className="_dsplFlx"  style={{margin: "10px 0 0 18px"}}>
							<div className="code" >
								{subaccountD?.subAccount} 
							</div>
							<div className="name">
								{subaccountD?. subAccountName}
							</div>
						</div>
						:null}
					<div className="flexSpace"/>
				</div>
			</div> :
			<div className="_dsplFlx " style={{margin: "38px 0"}}>
				<div className="flexSpace"/>
				<DropInput
					width={420}
					handleClick={handlePick}
				/>
				<div className="flexSpace"/>
			</div>
			}
			<div className="card">
				<button onClick={addExtraAccount2List}>
					Associar
				</button>
			</div>
			</div>
	)
}





export default LinkAccountPick;


