const ComprobanteFromBank  = ({ data, item, handleRefreshAll }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const navigate = useNavigate();


	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			let deb_type = "debit";
			let cred_type = "credit";
			let itmFrn = {...item};


			let amount = itmFrn?.amount;

			if(itmFrn?.amount<0){
				deb_type = "credit";
				cred_type = "debit";
				amount = itmFrn?.amount *-1;
			}

			
			
			let descr = itmFrn?.description;

			updFrm("description",descr);
			updFrm("date",itmFrn?.date *1);

			if(!itmFrn["document"]){
				updFrm("document",genAlphDay(itmFrn?.date *1)+"_"+gen4NumCode());
			}

			let categoryDtls =  getStore("categories_ids")?.[itmFrn?.categoryId];

			let rc1 = {};
			rc1.amount = amount;
			rc1.movementId = itmFrn?.movementId;
			rc1.description =  descr;
			rc1.date = itmFrn?.date;


			let rc2 = {...rc1};

			rc1["account"] = getStore("global_account_params")?.cash_bank.account;
			rc1.type = deb_type;
			

			rc2["account"] = categoryDtls?.account;
			if(categoryDtls?.subAccount){
				rc2["subAccount"] = categoryDtls?.subAccount;
			}
			rc2.type = cred_type;

			updStore("cmpListfromMbl",[rc2,rc1])
			set_obs(gen16CodeId())
		}
	},[getStore(frmNm)?.movementId]);

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	

	

	const openLinkCmp = async () => {
		if(hasWritePrivilege()){
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
		//	modaldata["content"] = <UpdFeedfromMobile confirm={refreshAccs} />;
			OpenModal(modaldata);
		}
	}

	
	
	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};

	const save  = async ()  => {
		let ffm = {...getStore(frmNm)};

		if(!ffm["date"]){
			ffm["date"] = (new Date()).getTime()+4800;
		}
		else{
			ffm["date"] =(new Date(ffm["date"])).getTime()+4800;
		}

		let comprobanteId = await generateComprobanteId(ffm["date"]);

		ffm["comprobanteId"] =comprobanteId;

		
		if(!ffm["document"]){
			ffm["document"] =  gen4NumCode()+"_"+genAlphDay(ffm["date"]);
		}

		let comp2save = [];


		getStore("cmpListfromMbl") && ObjectKeys(getStore("cmpListfromMbl"))?.map(async (element, indE)=>{
			let dataAcc = getStore("cmpListfromMbl")[element];
			if(!isNaN(dataAcc["amount"] * 1) && dataAcc["amount"]*1 > 0){
				let nnfrm = {...ffm};
				nnfrm["account"] =  dataAcc["account"];
				if(dataAcc["subAccount"]){
					nnfrm["subAccount"] =  dataAcc["subAccount"];
				}
				
				nnfrm["movementRef"] =  item["movementId"];
				nnfrm["type"] =  dataAcc["type"];
				nnfrm["amount"] =  dataAcc["amount"] *1;
				nnfrm["operationId"] = gen16CodeId();
				

				let bdyq5 = {...getStore(qryStore())?.add_opera};
				bdyq5.params = {
					businessId:  getStore("profileUser")?.businessId,
					year: (new Date(ffm["date"])).getFullYear()
				}
				bdyq5.form=nnfrm;
				comp2save.push(bdyq5)
			}
		});


		let bdyq2 = {...getStore(qryStore())?.upd__incms_expns};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			"movementId": item["movementId"],
			year:getStore("date_current_year"),
		}
		bdyq2.data2update={comprobanteId};
		comp2save.push(bdyq2)


		 // console.log(comp2save)
		
		/** */
		const promises = comp2save.map(async (qry2Sv) => {
			const res = fetchEncryptStream(qry2Sv);
			const td = await res;
			if (td) {
				//Log$$(td)
			}
        })      
        await Promise.all(promises);

		// T2jJVuvYOxZTTJ3h

		
		
		setTimeout(() => {
			updStore("cmpListfromMbl", null)
			updStore(frmNm, null)
			data?.modalID && CloseModal({id:data?.modalID});
			false && navigate({
				pathname: "/accounting-ledger" ,
				search: `?cId=${comprobanteId}`
			});
		}, 400);


	}


	const openImageCb =  (v) => {
		window.open(v)
	}

	const openImage =  () => {
	//	handleFetchImage(item, openImageCb);
	}

	

	return (
		<div style={{
			maxHeight: "90vh",
			minHeight:  "88vh",
			width: "960px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					Associar Asiento
				</p>
				<div className="flexSpace"/>
				{item?.imagePath? 
				<p className="group_title addBtn purple" onClick={openImage}>
					See Image
				</p>
				:null}
			</div>

			<div className="_dsplFlx ">
				<DateCalComponent init={getStore(frmNm)?.["date"]} updDate={(e)=>updFrm("date",e)} />
               
				<div className="flexSpace"/>
				
				<TextInput  
					init={getStore(frmNm)?.["document"]} 
					label={"Documento"} 
					width={120} 
					updChanges={(e)=>updFrm("document",e)}
				/>
	
			</div>
			<div className="_dsplFlx ">
				<TextInput  
					init={getStore(frmNm)?.["description"]} 
					label={"Descripcion"} 
					width={520} 
					updChanges={(e)=>updFrm("description",e)}
				/>
			</div>
			<div style={{marginTop:19}}>
				<CardAssientos 
					item={getStore("cmpListfromMbl")} 
					updFrm={updFrm}
					document={getStore(frmNm)?.["document"]}
				/>
			</div>

			<div className="_dsplFlx "  style={{margin:"32px 32px 0 0"}}>
				<div className="flexSpace"/>
				<GrayButton color={"#007bfc"} clickHandler={save} label={"Salvar"}/>
			</div>

			
		</div>
	)
}
export default ComprobanteFromBank;





