import React , {useEffect, useRef, useState} from "react";

import "./styles.css"
import { getStore, parseDateMMDDYYYY, gen16CodeId, downloadCSVFromJson, isSuperUser, updStore, parseFloatToDecimal, parseQuery, offset, isValidFunction, setIntervalX } from "../../../stores/Utils";
import { get_filter_by_acc, calcSubmayor, prepareSubMayorDatatoCvs, getPrevBalance, getall_bankRcrd } from "../services/server_fetching";
import {  useNavigate } from "react-router";
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import ViewBankConsoldidation from "./ViewBankConsoldidation";
import { LoadingColorSpinner_Cmpt, MonthPicker_Cmpt, SvgIcon_Cmpt } from "../../../components";
import { NavLink } from "react-router-dom";
import DeleteAlert from "../../Inventory/component/deleteAlert";
import { delete_Comprobante } from "../../Comprobantes/services/server_fetching";


const MonthPicker = MonthPicker_Cmpt();
const LoadingColorSpinner = LoadingColorSpinner_Cmpt();

const Svg = SvgIcon_Cmpt();


const coll2list = "submFilterData"

const ViewComprobante  = ({ data, accountForm }) => {
	const [, set_obs] = useState(0);
	const [loading, setLoading] = useState(true);

	const [range, set_range] = useState(64);

	const listDataRef = useRef(null);

	let item = getStore("submayor_group");


	
	useEffect(() => {
		initPickMonth();
	},[accountForm]);



	const handleRefreshAll =  () => {
		get_filter_by_acc(accountForm,loadList);
	}

	const updObs =  () => {
		set_obs(gen16CodeId())
	}


	let accountD = getStore("account_ids")?.[accountForm?.account];
	let subaccountD = getStore("sub_account_ids")?.[accountForm?.subAccount];

	
	const close =  (element) => {
		CloseModal({id:data.modalID});
		
	}
	

	const openCalendarModalPicker =  () => {
		let ccc = calcSubmayor(item?.operations, accountD?.code,subaccountD?.subAccount);
		
		downloadCSVFromJson('export_submayor_' +accountD?.code+"_"+(subaccountD?.subAccount? subaccountD?.subAccount+"_" : "") +gen16CodeId()+'.csv',prepareSubMayorDatatoCvs(ccc,accountD?.code,subaccountD?.subAccount));

	};


	const openBankCon =  () => {
		
		let modal_data = {};
		modal_data["zIndex"] = 450;
		modal_data["height"] = "80vh";
		// data['observeResize']=true;
		modal_data["props"] = { minHeight: "1vh", overlay: true };
		modal_data["content"] = 
			<ViewBankConsoldidation 
				accountD={accountD}
				subaccountD={subaccountD}
				operations={item?.operations}
				accountForm={accountForm}
			/>
		OpenModal(modal_data);
		CloseModal({id:data.modalID});
	}

	const initPickMonth =  () => {

		let YY = getStore("date_current_year");
		let now = (new Date());
		let mnth = now.getMonth() +1;

		let dt = (new Date(mnth+"/01/"+YY));
		let Nt = (new Date((mnth+1)+"/01/"+YY));
		let initDate = dt.getTime();
		let lastDate = Nt.getTime() - 600;

		updStore("date_range_submayor", {initDate,lastDate} );
		get_filter_by_acc(accountForm,loadList);
	}


	const handlePickMonth =  ({initDate,lastDate}) => {
		setLoading(true)
		updStore("date_range_submayor", {initDate,lastDate} );
		get_filter_by_acc(accountForm,loadList);
	}


	
	const cb_result = async (f, v) => {
		if(range!==64){
			set_range(64);
		}
		else{
			set_obs(gen16CodeId())
		}
	};


	const loadMore=  () => {
		set_range(v=>v+64)
	}

	const loadList =  () => {

		
		let docdata = getStore("submayor_group")?.operations && calcSubmayor(getStore("submayor_group")?.operations, accountForm?.account, accountForm?.subAccount, monthInit)
				
		updStore(coll2list,docdata);
		
		cb_result();

		let factor = Math.ceil(getStore("submayor_group")?.operations.length / 64);

		setIntervalX(loadMore, 1250, factor)

		setTimeout(() => {
			setLoading(false)
		}, 230);
		
	};


	let monthInit = (new Date(getStore("date_range_submayor")?.initDate)).getMonth();

	let prevBalance = getPrevBalance(monthInit, accountForm);

	return (
		<div style={{
			height: "96vh",
			width: "90vw",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 10px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect"  >
					{ "SubMayor de la Cuenta"}
				</p>
				
				<div className="flexSpace"/>
				<p className="group_title addBtn purple" onClick={openCalendarModalPicker}>
					Exportar a CSV
				</p>
				{isSuperUser() && getStore("global_account_params")?.cash_bank?.account ===  accountD?.accountId ?
					<div className="group_title addBtn purple upl" onClick={openBankCon}>
						Consolidacion Bancaria
					</div>
				:null}
			</div>
		


			
			
			
			<div className="_dsplFlx cmp_dtls">
				<div className=" acc_dtls" style={{marginTop: 10}}>
					<div className="_dsplFlx"  >
						<div className="code" data-ref={`${accountD?.accountId}`} style={{color: "var(--hrm_palette-blue-purple)"}}>
							{accountD?.code} 
							
							
						</div>
						<div className="name" style={{color:"var(--hrm_palette-imput-label_gray)"}}>
							{accountD?. name}
						</div>
					</div>
					<div className="flexSpace"/>
					{subaccountD ?
					<div className="_dsplFlx"  style={{margin: "10px 0 0 18px"}}>
						<div className="code"  data-ref={`${subaccountD?.sub_accountId}`} style={{color:"var(--hrm_palette-inverse-background-b)"}} >
							{subaccountD?.subAccount} 
						</div>
						<div className="name"  style={{color:"var(--hrm_palette-imput-label_gray)"}}>
							{subaccountD?. subAccountName}
						</div>
				   	</div>
					:null}
				</div>
				<div className="flexSpace"/>
				<div className="_dsplFlx acc_dtls" style={{margin: "18px 10px 0 0"}} >
					<div className="name"  style={{color:"var(--hrm_palette-imput-label_gray)"}}>
						Saldo Inicial
					</div>
					<div className="code" style={{ marginLeft: 10,color: "var(--hrm_palette-blue-purple)"}}>
						{(prevBalance *1).toFixed(2) }
					</div>
				</div>
				<div className="_dsplFlx"  >
					<div style={{marginTop: 6}}>
						<MonthPicker 
							onSelect={handlePickMonth} 
							initMonth={monthInit} 
							year={getStore("date_current_year")}
							direction={"right"}
							background={"#f9f9f9"}
							color={"var(--hrm_palette-blue-purple)"}
						/>
					</div>
				</div>
			</div>




			
			
			<div className="_dsplFlx hdr_bar purple">
				<div className="tr_bar_20">
					Comprobante
				</div>
				<div className="tr_bar_10">
					Fecha
				</div>
				<div className="tr_bar_35">
					Documento
				</div>
				<div className="tr_bar_10">
					Debito
				</div>
				<div className="tr_bar_10">
					Credito
				</div>
				<div className="tr_bar_10">
					Saldo
				</div>
				<div className="tr_bar_5"/>
			</div>
   
			{loading? 
			<div className="_dsplFlx  spaceAround flxWrp" style={{marginTop:140}}>
				<div className="icon_compr _dsplFlx" >
					<div className="lbl_saving ">
						Cargando ... 
					</div>
					<LoadingColorSpinner stroke={"var(--hrm_palette-blue-purple)"} size={24} strokeW={8}/>
				</div>
			</div>
			:
			<div  id={"scollSubMayorList"}  className="clients_container"  ref={listDataRef}  style={{height: "calc(96vh - 185px)"}}>
				
			{getStore(coll2list) && getStore(coll2list)?.map((element,index) => {
				return	(
					<SubMayorAccItem 
						element={element}
						range2Scroll={range-index===32}
						show={index < range}
						inx={index}
						handleRefreshAll={handleRefreshAll}
						key={index}
						close={close}
					/>
				)
			})}
			</div>
}
		</div>
	);
};

export default ViewComprobante;





const SubMayorAccItem = ({element, show, range2Scroll, close, inx, handleRefreshAll}) =>{


	const [, set_obs] = useState(0);

	

	const itemRef = useRef(null);
	


	
	if(!show){
		return null;
	}
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	
	const deleteComprobante =  () => {
		
		delete_Comprobante([element], handleRefreshAll)
	}
	



	
	
	const OpenDeleteAlert =  (modalId) => {
		let modaldata = {};
		modaldata["id"] = modalId;
		modaldata["zIndex"] = 490;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		let bdyM = <div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Una vez eliminado no podra ser recuperado"}
			</h4>
		</div>

		let titleCm = <div className="_dsplFlx ">
			<div className="centerBx"  style={{padding: 4, marginRight: 20}}>
				<Svg name={"outline_delete"} color={"#c62828"}/>
			</div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Eliminar Registro !!!"}
			</h4>
		</div>



		modaldata["content"] = <DeleteAlert
			label={titleCm} 
			labelColor={"var(--hrm_palette-selected-nav-text)"} 
			body={bdyM} 
			btnConfirm={"Eliminar"}
			confirm={deleteComprobante} 
			item={element}
			done={((v)=>{
				v && CloseModal({id:v});
			})}
		/>
		let lastTimeCallModal = getStore("lastTimeCall22Modal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCall22Modal", Date.now()+320);
			OpenModal(modaldata);
		}
	}


	return(
		<div className="_dsplFlx hdr_bar" 
			ref={itemRef} 
			item-index={`${inx}`}
			{...(range2Scroll ? { "watching-scroll": "true" } : "")}
		>
			<div className="tr_bar_20 comprobante_id" onClick={()=>close(element)}>
				<NavLink to={{
					pathname: "/accounting-ledger" ,
					search: `?cId=${element.comprobanteId}`
				}}>
					{element.comprobanteId}
				</NavLink>
			</div>
			<div className="tr_bar_10">
				{element.date && parseDateMMDDYYYY(element.date)}
			</div>
			<div className="tr_bar_35">
				{element.document}
			</div>
			<div className="tr_bar_10">
				{(element.debit*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_10">
				{(element.credit*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_10">
				{(element.saldo*1)?.toFixed(2)}
			</div>
			{(element.debit*1 - element.credit*1) === 0? 
				<div className="icon tr_bar_5" onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"} color={"#c62828"}/>
				</div>
				:null
			}
		</div>
	)
}  



