import React , {useEffect, useState, memo, useRef} from "react";

import "./styles.css"
import { getStore, parseDateMMDDYYYY, gen16CodeId,  updStore, ObjectKeys,  qryStore, fetchEncryptStream, parseFloatToDecimal, isValidFunction, callbackOnMemory, sortByObjectKey, offset } from "../../../stores/Utils";

import { OpenModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt, SearchInput_Cmpt, CheckBoxSlide_Cmpt, LoadingColorSpinner_Cmpt } from "../../../components";
import {  getall_bankRcrd, getPrevBalance } from "../services/server_fetching";

import ViewVerifyManual from "./ViewVerifyManual";
import ViewCompareComprobante from "./ViewCompareComprobante";
import DeleteAlert from "./deleteAlert";
import { NavLink } from "react-router-dom";

const Svg = SvgIcon_Cmpt();

const SearchInput = SearchInput_Cmpt();


const CheckBoxSlide = CheckBoxSlide_Cmpt();
const LoadingColorSpinner = LoadingColorSpinner_Cmpt();



const coll2list = "bank_verify_consolidation"

const ViewVerifyBankConsoldidation  = ({ reCompare, navTo,  accountD, accountForm, loadingV})=>{
	const [obs, set_obs] = useState(0);
	const [search, setSearch] = useState("");
	const [loading, set_loading] = useState(false);

	const [hasWarning, setHasWarning] = useState(false);


	useEffect(() => {
		handleFilter();
	},[accountD]);


	const upd2Obs =  () => {
		set_obs(gen16CodeId());
		set_loading(false);
	}

	const handleFilter =  () => {
		updStore(coll2list,filterBankValidate(getStore("ourBank_filtered")?.verified, search, hasWarning));
		upd2Obs();
	}

	const changeFilter =  (v) => {
		setTimeout(() => {
			updStore(coll2list,filterBankValidate(getStore("ourBank_filtered")?.verified, search, v));
			upd2Obs();
		}, 200);
		setHasWarning(v)
	};




	const handleChange =  (v) => {
		!loading && set_loading(true);
		setSearch(v)
	}





	if(loadingV){
		return <LoadingData />
	}


	let monthInit = (new Date(getStore("date_range_submayor")?.initDate)).getMonth()+1;
	let prevBalance = getPrevBalance(monthInit,accountForm);

	return (
		<div >
			
			<div className="_dsplFlx " style={{marginTop:14}}>
					<div  style={{marginTop:11}}>
						<SearchInput
							placeholder={"Buscar ...."} 
							width={560}
							obs={set_obs}
							fetchData={handleFilter}
							loading={loading}
							change={handleChange}
							callempty={handleFilter}
							keyFlds={"search_h65767"}
						/>
					</div>
					
					<div style={{marginLeft:15}}/>
					<div>
						<div className="_dsplFlx " style={{
								marginTop: 20,
							}}>
								<CheckBoxSlide
									initvalue={hasWarning}
									keyCode={72}
									updChange={(e)=>changeFilter(e)}
									color={"var(--hrm_palette-color-orange-800)"}
								/>
								<span className={`checklabel`}>
									{"Regitros con alertas"}
								</span>
						</div>
					</div>
					<div className="flexSpace"/>
					<div className="_dsplFlx ">
						<div className="total_comprobante_title">
							No de Registros: 
						</div>
						<div className="total_comprobante gray">
							<span>
								{getStore(coll2list).length }
							</span>
						</div>
					</div>
				</div>
			
			
				<div className="_dsplFlx"  style={{marginTop:15}}>
					<div className="_dsplFlx"  >
						<div className="igLyC_sum jyoO_sum" style={{color: "var(--hrm_palette-item_coll_gray)"}}>
							{"Saldo submayor Banco:"} 
						</div>
						<div className="igLyC_sum jyo3_sum " style={{color: "var(--hrm_palette-inverse-background-b)"}}>
							{accountD.type === "credit" ?  (prevBalance *-1).toFixed(2): (prevBalance *1).toFixed(2) }
						</div>
					</div>
					<div className="flexSpace"/>
					<div className="_dsplFlx"  >
						<div className="igLyC_sum jyoO_sum" style={{color: "var(--hrm_palette-item_coll_gray)"}}>
							{"Total verificado:"} 
						</div>
						<div className="igLyC_sum jyo3_sum " style={{color: "var(--hrm_palette-inverse-background-b)"}}>
							{SumBalance(getStore("ourBank_filtered")?.verified)?.toFixed(2)} 
						</div>
					</div>
					
					
				</div>
				<div style={{marginTop:15}}/>

					<ListItemBankVerified  
						search={search}
						filter={hasWarning}
						navTo={navTo}
						reCompare={reCompare}
						
					/>
				
		</div>
	);
};




export default ViewVerifyBankConsoldidation;






const LoadingData = ({ })=>{

	return (
			<div style={{minHeight:"calc(70vh - 1px)"}}>
					<div className="load_animation"/>
					<div className="_dsplFlx "  style={{marginTop:32}}>
						<div className="flexSpace"/>
						<div className="icon_compr _dsplFlx" >
							<div className="lbl_saving">
									Loading ... 
							</div>
							<LoadingColorSpinner stroke={"#646cff"} size={24} strokeW={8}/>
						</div>
						<div className="flexSpace"/>
					</div>
		</div>
	)
}






const ListItemBankVerified = ({ navTo, reCompare })=>{
	
	const [range, set_Range] = useState(64);

	const updRange =  () => {
		
		set_Range(prev=>prev+64);
	}
	
	return (
		<div>
				<div className="_dsplFlx hdr_bar purple">
					<div className="tr_bar_15">
						Comprobante
					</div>
					<div className="tr_bar_10">
						Fecha
					</div>
					<div className="tr_bar_40">
						Descripcion
					</div>
					<div className="tr_bar_10">
						No cheque
					</div>
					<div className="tr_bar_10">
						Importe
					</div>
					<div className="tr_bar_10">
						Documento
					</div>
				</div>

				<div id={"scollVhBankVerified"} className="scollVh"  style={{height: "calc(96vh - 235px)"}}>
				{getStore(coll2list) && getStore(coll2list)?.map((element,ind43) => {
					return(
						<ItemBank
							element={element}
							
							inx={ind43}
							key={ind43+"_bankItm"}
							navTo={navTo}
							reCompare={reCompare}
							verifyManual={true}
							range2Scroll={range-ind43===32}
							show={ind43 < range}
							updRange={updRange}
							elementId={element.bankRecordId}
						/>
					)
				})}
			</div>
		</div>
	)
}






const ItemBankComponent = ({element, show,  navTo, reCompare, inx, range2Scroll, verifyManual, updRange  })=>{

	const [loading, set_loading] = useState(false);




	const itemRef = useRef(null);
	const scrollRef = useRef(0);
	const inViewPort = useRef(false);
	const refInt = useRef(null);

					

	useEffect(() => {

		if(range2Scroll){
			refInt.current = 
			setInterval(() => {
				let fff = document.getElementById("scollVhBankVerified");
				if(!inViewPort.current && scrollRef.current !== fff.scrollTop){
					scrollRef.current = fff.scrollTop;
					let dmz = offset(itemRef.current);
					if(dmz.top + dmz.height - scrollRef.current < 0){
						if(isValidFunction(updRange)){
							inViewPort.current = true;
							updRange();
						}
					}
				}
			}, 250); 
		}
	  return () => {
		refInt.current && clearInterval(refInt.current);
	  }
	}, [range2Scroll]);

	
	if(!show){
		return null;
	}

	const doneConfirmLink =  () => {
		set_loading(false)
	}
	

	const send2Compare =  () => {
		reCompare(doneConfirmLink)
	}


	const openVerifyManual =  () => {
		
		let modal_data = {};
		modal_data["zIndex"] = 450;
		modal_data["height"] = "80vh";
		// data['observeResize']=true;
		modal_data["props"] = { minHeight: "1vh", overlay: true };
		modal_data["content"] = 
			<ViewVerifyManual  item={element} confirm={send2Compare}  />
		OpenModal(modal_data);
	}

	
	const openVerifyCompare =  () => {
		
		let modal_data = {};
		modal_data["zIndex"] = 450;
		modal_data["height"] = "80vh";
		// data['observeResize']=true;
		modal_data["props"] = { minHeight: "1vh", overlay: true };
		modal_data["content"] = 
			<ViewCompareComprobante  item={element} confirm={send2Compare} />
		OpenModal(modal_data);
	}

	const confirmLink = async (element) => {
		if(verifyManual){
			openVerifyCompare();
		}
		else if(!element.linkId && element.operationId){
			openVerifyCompare();
		}else{
			openVerifyManual();
		}
	}



	const confirmDelete = async  (v)  => {
		let bdyq2 = {...getStore(qryStore())?.delete_bank_bUp};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			bankRecordId: element.bankRecordId,
			year: getStore("date_current_year")

		}
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			getall_bankRcrd(send2Compare);
		}
	};



	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCallModal", Date.now()+320);
			
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <DeleteAlert 
				confirm={confirmDelete}
				lbl_p={"Eliminar Movimiento del Banco"} 
				lbl_span={"Una vez eliminado no podra ser recuperado"}
			/>
			OpenModal(modaldata);
		}
	}
	


	let cmpBnk = getStore("submayor_list")?.[element.linkId];
	let bnkAmount = (cmpBnk?.type === "credit" ? -1 : 1) * cmpBnk?.amount;

	let isDupl =  getStore("ourBank_filtered")?.verified_duplicatedLink[element.bankRecordId];
	let hasWarning = bnkAmount - element?.amount !==0 || isDupl;
	
	return(
		<div className="_dsplFlx hdr_bar " ref={itemRef} item-index={`${inx}`}>

			
			<div className="tr_bar_15 comprobante_id _dsplFlx" >
				{loading?
				<div className="icon_compr" >
						<LoadingColorSpinner stroke={"#646cff"} size={24} strokeW={8}/>
					</div>
				:<div className="icon_compr" onClick={()=>confirmLink(element)}>
					<Svg 
						name={hasWarning? "alert": element.linkId ? "check_circle":  element.comprobanteId?"link":"alert"} 
						color={hasWarning? "var(--hrm_palette-color-orange-800)": element.linkId ?"var(--hrm_palette-success-fg)": element.comprobanteId?"var(--hrm_palette-mono-filled-hover)":"#c62828"}
					/>
				</div>
				}
				
				<div className="flexSpace"/>
				<div onClick={()=>navTo(element)}>
					<NavLink to={{
						pathname: "/accounting-ledger" ,
						search: `?cId=${element.comprobanteId}`
					}}>
						{element.comprobanteId}
					</NavLink>
				</div>
				<div className="flexSpace"/>
			</div>
			<div className="tr_bar_10">
				{element.date && parseDateMMDDYYYY(element.date)}
			</div>
			<div className="tr_bar_40 desc_font">
				{element.description}
			</div>
			<div className="tr_bar_10">
				{element.checkOrSlip}
			</div>
			
			<div className="tr_bar_10">
				{(element.amount*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_10">
				{element.document}
			</div>
			<div className="icon_2rmv" onClick={OpenDeleteAlert}>
				<Svg 
					name={"outline_delete"} 
					color={"#c62828"}
				/>
			</div>
		</div>
	)

}






const customComparator = (prevProps, nextProps) => {
	return nextProps.elementId === prevProps.elementId && nextProps.show === prevProps.show  && nextProps.range2Scroll === prevProps.range2Scroll; 
};

export const ItemBank =  memo(ItemBankComponent, customComparator);







export const filterBankValidate = (arr1, search, filter) => 
    callbackOnMemory(
        "filterBankValidate",
        [arr1, search, filter],() => {
			let newA = []
			ObjectKeys(arr1)?.map((s) => {
				let itm = arr1[s];
				let isV = true;
				
				if(itm.status!==9){
					isV = false;
				}
				
				if(search){
					if(!compareSearch(itm,search)){
						isV = false;
					}
				}

				if(filter){
					let cmpBnk = getStore("submayor_list")?.[itm.linkId];
					let bnkAmount = (cmpBnk?.type === "credit" ? -1 : 1) * cmpBnk?.amount;
				
					let isDupl =  getStore("ourBank_filtered")?.verified_duplicatedLink[itm.bankRecordId];
					let hasWarning = bnkAmount - itm?.amount !==0 || isDupl;
					if(!hasWarning){
						isV = false;
					}
				}
				if(isV){
					newA.push(itm)
				}
			});
			// 
			return sortByObjectKey(newA,"date");
    }
);




const compareSearch = (itm,qry) =>{
	let srch = qry.toLowerCase();
	let isValid = false;
	["description", "amount","document", "comprobanteId", "dateDDMMYYYY"].map(fld=>{
		if( itm[fld] && itm[fld]?.toString()?.toLowerCase()?.indexOf(srch)>=0){
			isValid = true;
		}
	})
	return isValid;
}






const SumBalance = (obj) => {
	let balance = 0;
	obj && ObjectKeys(obj)?.map((flds, indE)=>{
		let amount = (obj[flds].amount*1);
		balance =  parseFloatToDecimal(balance,2)*1 + parseFloatToDecimal(amount,2)*1;
	});
	return  balance;
}  



export const rangeArrV = (arr, range) =>
callbackOnMemory(
	"rangeArrV",
	[arr,range],
	() => {
        return arr ?arr.slice(0,range) : [];
    }
);



